const servers = ['s0', 's1', 's2', 's3'];

const route = (key) => servers[hash(key) % servers.length];

// Drop s1 → the divisor changes → almost every key moves.
// With N servers, removing one remaps roughly (N-1)/N of keys:
//   4 servers → ~75%      10 servers → ~90%

// positions: sorted [{ hash, server }]
const ring = [];

function addServer(name, vnodes = 150) {
  for (let i = 0; i < vnodes; i++) {
    ring.push({ hash: hash(`${name}#${i}`), server: name });
  }
  ring.sort((a, b) => a.hash - b.hash);
}

function locate(key) {
  const h = hash(key);

  let lo = 0, hi = ring.length - 1;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (ring[mid].hash < h) lo = mid + 1;
    else hi = mid;
  }

  // wrap past the end of the ring back to the first position
  return ring[ring[lo].hash >= h ? lo : 0].server;
}

// One token per server: load spread is wild, and losing a server
// dumps its whole range onto ONE neighbour, which then falls over.
//
// Load spread shrinks roughly as 1/sqrt(V):
//   V=1    → 2-4x imbalance is ordinary
//   V=100  → ~10%
//   V=1000 → ~3%
//
// 150 sits near the knee of that curve.

function preferenceList(key, r = 3) {
  const start = indexOf(hash(key));
  const chosen = [];

  for (let i = 0; i < ring.length && chosen.length < r; i++) {
    const s = ring[(start + i) % ring.length].server;
    if (!chosen.includes(s)) chosen.push(s); // skip repeat positions
  }
  return chosen;
}

